  if (page === 'notes') return `<div class="quick-note"><div class="quick-page-title"><h2>A quick note</h2>${btn('open-hub', 'Open Notetaker', 'expand', 'text-button')}</div><textarea data-field="quick-note" placeholder="A thought, before it goes…" aria-label="Quick note">${esc(quickNote)}</textarea><footer><span>Saved only on this computer</span>${btn('quick-save-note', 'Save note', 'note', 'button primary')}</footer><div class="quick-recent">${sortedNotes(state.notes).slice(0, 2).map(n => `<button data-action="open-note" data-id="${esc(n.id)}">${icon('note', 13)} ${esc(noteTitle(n))}${icon('chevron', 12)}</button>`).join('')}</div></div>`;
  if (page === 'focus') return `<div class="quick-focus">${buddy(75, state.settings.buddy, focusRunning ? 'focus' : 'idle')}<div><span>ONE THING AT A TIME</span><strong data-focus-time>${formatDuration(focusRemaining)}</strong><p>${focusRunning ? 'A little space to concentrate.' : 'Whenever you’re ready.'}</p></div><div>${btn('focus-toggle', focusRunning ? 'Pause' : 'Start focus', focusRunning ? 'pause' : 'play', 'button primary')}${btn('open-hub', 'Your focus space', 'expand', 'text-button')}</div></div>`;
