  return `<div class="notes-page"><div class="notes-list"><div class="notes-heading"><h2>Notetaker <span>${state.notes.length}</span></h2>${ibtn('new-note', 'plus', 'New note')}</div><label class="search-field">${icon('search', 14)}<input data-field="note-search" placeholder="Find a thought…" value="${esc(noteQuery)}" aria-label="Search notes"></label><button class="meeting-button" data-action="new-meeting">${icon('mic', 14)} New meeting note</button><div class="note-items">${notes.length ? notes.map(n => `<button class="note-item ${n.id === selectedNote ? 'selected' : ''}" data-action="open-note" data-id="${esc(n.id)}"><div>${n.pinned ? icon('pin', 12) : n.kind === 'meeting' ? icon('mic', 12) : ''}<strong>${esc(noteTitle(n))}</strong></div><p>${esc(n.body.replace(/[#*`]/g, '').slice(0, 100) || 'A little room for an idea…')}</p><small>${dateLabel(n.updatedAt)}<span>${wordCount(n.body)} words</span></small></button>`).join('') : `<div class="list-empty">${icon('note', 24)}<span>${noteQuery ? 'No matching notes' : 'Your thoughts belong here'}</span></div>`}</div></div><div class="note-editor">${note ? `<div class="editor-toolbar"><span>${icon(note.kind === 'meeting' ? 'mic' : 'note', 13)} ${note.kind === 'meeting' ? 'MEETING NOTE' : 'PERSONAL NOTE'}</span><div>${ibtn('pin-note', 'pin', note.pinned ? 'Unpin note' : 'Pin note', `aria-pressed="${note.pinned}"`)}${ibtn('export-note', 'download', 'Export note')}${ibtn('delete-note', 'trash', 'Delete note')}</div></div><input class="note-title" data-field="note-title" placeholder="Untitled thought" value="${esc(note.title)}" aria-label="Note title"><textarea class="note-body" data-field="note-body" placeholder="Make a little space for what’s on your mind…" aria-label="Note body">${esc(note.body)}</textarea><div class="editor-footer"><span data-save-state>Saved on this device</span><span data-word-count>${wordCount(note.body)} words</span>${note.kind === 'meeting' ? btn('meeting-record', 'Capture with dictation', 'mic', 'text-button') + btn('summarize-note', 'Summarize with Lu', 'sparkle', 'text-button') : btn('note-to-chat', 'Ask Lu about this', 'sparkle', 'text-button')}</div>` : emptyState('note', 'Every thought starts somewhere.', 'An idea, a list, a small reminder. Make it a note.', btn('new-note', 'A new thought', 'plus', 'button primary'))}</div></div>`;
