  return `<div class="page focus-page">${heading('A LITTLE ROOM TO CONCENTRATE', 'One thing at a time.', 'You don’t have to do everything. Just the next thing.')}<div class="focus-tabs"><button data-action="focus-kind" data-kind="focus" class="${focusKind === 'focus' ? 'selected' : ''}">Deep focus</button><button data-action="focus-kind" data-kind="break" class="${focusKind === 'break' ? 'selected' : ''}">A little break</button></div><div class="focus-stage"><div class="focus-ring" style="--progress:${(1 - focusRemaining / focusTotal) * 360}deg"><div class="focus-ring-inner"><span class="eyebrow">${focusKind === 'focus' ? 'MAKE A LITTLE SPACE' : 'TAKE A BREATH'}</span><strong data-focus-time>${formatDuration(focusRemaining)}</strong><span data-focus-label>${focusRunning ? 'You’re right where you need to be.' : 'Whenever you’re ready.'}</span></div></div><div class="focus-controls">${ibtn('focus-reset', 'reset', 'Reset timer')}${btn('focus-toggle', focusRunning ? 'Pause' : focusRemaining < focusTotal ? 'Keep going' : focusKind === 'focus' ? 'Let’s focus' : 'Take a break', focusRunning ? 'pause' : 'play', 'button primary')}${ibtn('focus-settings', 'settings', 'Timer settings')}</div><div class="focus-presets">${(focusKind === 'focus' ? [15, 25, 45, 60] : [3, 5, 10, 15]).map(m => `<button data-action="focus-preset" data-minutes="${m}" class="${focusTotal === m * 60 ? 'selected' : ''}">${m} min</button>`).join('')}</div></div><div class="focus-stats"><div>${icon('focus', 19)}<strong>${mins}<span> minutes of focus</span></strong></div><div>${icon('check', 19)}<strong>${completed}<span> sessions today</span></strong></div><div>${icon('coffee', 19)}<span>A little progress counts.</span></div></div></div>`;
