function toggleRow(key: keyof Settings, title: string, description: string, disabled = false) { return `<label class="setting-row"><span><strong>${title}</strong><small>${description}</small></span><input type="checkbox" class="switch" data-setting="${key}" ${state.settings[key] ? 'checked' : ''} ${disabled ? 'disabled' : ''}><span class="switch-track"></span></label>`; }
